import App, {
  BaseControllerClass,
  ModuleDefinition,
  ControllerOptions,
  type ControllerClass,
} from 'cerebral'
import { Injectable } from '@angular/core'
import Model from 'cerebral/lib/Model'

@Injectable({ providedIn: 'root' })
export class AppService extends BaseControllerClass {
  flush!: (force?: boolean) => void
  updateComponents!: (changes: any[], force: boolean) => void

  constructor(rootModule: ModuleDefinition, options?: ControllerOptions) {
    options = options || {}
    if (!options.Model) {
      options.Model = Model
    }
    super(rootModule, options, {})
    const app = App(rootModule, options)
    return app as ControllerClass
  }
}
